EXPORT ZZT_COMPLEXMIX() BEGIN
LOCAL R,E,O:={}; HComplex:=1;
A:=0; E:=0; R:=-99;
IFERR R:=stddev([(1,4),3],[1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([1,3],[(1,4),3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([(1,-4),3],[1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([(1,0),3],[1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([3,(1,4)],[3,1]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([(1,4),3],[.5,1.5]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
ZZT_TICK(D,V) BEGIN A:=A*10+D; RETURN V; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;

EXPORT ZZT_COMPLEXMIX() BEGIN
LOCAL R,E,O:={}; HComplex:=1;
A:=0; E:=0; R:=-99;
IFERR R:=stddev([(ZZT_TICK(1,1),ZZT_TICK(2,4)),ZZT_TICK(3,3)],[1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([1,3],[(ZZT_TICK(1,1),ZZT_TICK(2,4)),ZZT_TICK(3,3)]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([(ZZT_TICK(1,1),ZZT_TICK(2,4)),ZZT_TICK(3,3),ZZT_TICK(4,6)],[1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([(ZZT_TICK(1,1),ZZT_TICK(2,4)),ZZT_TICK(3,3)],[1,3,5]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([1,3],[(ZZT_TICK(1,1),ZZT_TICK(2,4)),ZZT_TICK(3,3),ZZT_TICK(4,6)]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([1,3,5],[(ZZT_TICK(1,1),ZZT_TICK(2,4)),ZZT_TICK(3,3)]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
ZZT_TICK(D,V) BEGIN A:=A*10+D; RETURN V; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;

EXPORT ZZT_COMPLEXMIX() BEGIN
LOCAL R,E,O:={}; HComplex:=1;
A:=0; E:=0; R:=-99;
IFERR R:=stddev([(ZZT_FAIL(1),ZZT_TICK(2,4)),ZZT_TICK(3,3)],[1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([1,3],[(ZZT_TICK(1,1),ZZT_FAIL(2)),ZZT_TICK(3,3)]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([(ZZT_TICK(1,1),ZZT_TICK(2,4)),ZZT_TICK(3,3)],{ZZT_TICK(4,1),ZZT_TICK(5,3)}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev({ZZT_TICK(1,1),ZZT_TICK(2,3)},[(ZZT_TICK(3,1),ZZT_TICK(4,4)),ZZT_TICK(5,3)]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([(ZZT_TICK(1,1),ZZT_TICK(2,4)),ZZT_TICK(3,3)],{ZZT_FAIL(4),ZZT_TICK(5,3)}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
ZZT_TICK(D,V) BEGIN A:=A*10+D; RETURN V; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;

EXPORT ZZT_COMPLEXMIX() BEGIN
LOCAL R,E,O:={}; HComplex:=1;
A:=0; E:=0; R:=-99;
IFERR R:=stddev([1,3],[1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([1,3],{1,1}); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([0+1,3],[1,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=stddev([(1,4),3],[0+0,3]); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
A:=0; E:=0; R:=-99;
IFERR R:=ZZT_FAIL(1); THEN E:=1; END;
O:=CONCAT(O,{{A,E,TYPE(R),STRING(R)}});
RETURN O; END;
ZZT_TICK(D,V) BEGIN A:=A*10+D; RETURN V; END;
ZZT_FAIL(D) BEGIN A:=A*10+D; RETURN 1/0; END;
